use axum::extract::{Path, State};
use axum::Json;
use sqlx::PgPool;

#[derive(serde::Serialize, sqlx::FromRow)]
pub struct User {
    pub id: i64,
    pub name: String,
}

pub async fn get_user(
    State(pool): State<PgPool>,
    Path(id): Path<i64>,
) -> Json<User> {
    let user = sqlx::query_as::<_, User>("SELECT id, name FROM users WHERE id = $1")
        .bind(id)
        .fetch_one(&pool)
        .await
        .unwrap();
    Json(user)
}

